CPPUNIT_TEST_SUITE_REGISTRATION(FalconTests);

namespace
{
	const std::vector<unsigned long> allParameterSets = {
		CKP_FALCON_512, CKP_FALCON_1024
	};

	bool verifyFalconSignature(FalconPublicKey* publicKey,
		const ByteString& data, const ByteString& signature)
	{
		OSSLFalconPublicKey* osslPublicKey =
			static_cast<OSSLFalconPublicKey*>(publicKey);
		EVP_PKEY* pkey = osslPublicKey->getOSSLKey();
		if (pkey == NULL) return false;

		EVP_MD_CTX* context = EVP_MD_CTX_new();
		if (context == NULL) return false;
		const bool result =
			EVP_DigestVerifyInit(context, NULL, NULL, NULL, pkey) > 0 &&
			EVP_DigestVerify(context, signature.const_byte_str(),
				signature.size(), data.const_byte_str(), data.size()) == 1;
		EVP_MD_CTX_free(context);
		return result;
	}
}

void FalconTests::setUp()
{
	falcon = CryptoFactory::i()->getAsymmetricAlgorithm(AsymAlgo::FALCON);
	CPPUNIT_ASSERT(falcon != NULL);
}

void FalconTests::tearDown()
{
	if (falcon != NULL)
	{
		CryptoFactory::i()->recycleAsymmetricAlgorithm(falcon);
		falcon = NULL;
	}

	fflush(stdout);
}

void FalconTests::testKeyGeneration()
{
	for (const unsigned long parameterSet : allParameterSets)
	{
		const bool isFalcon512 =
			parameterSet == FalconParameters::FALCON_512_PARAMETER_SET;
		const unsigned long publicKeyLength = isFalcon512 ?
			FalconParameters::FALCON_512_PUB_LENGTH :
			FalconParameters::FALCON_1024_PUB_LENGTH;
		const unsigned long privateKeyLength = isFalcon512 ?
			FalconParameters::FALCON_512_PRIV_LENGTH :
			FalconParameters::FALCON_1024_PRIV_LENGTH;
		const unsigned long signatureLength = isFalcon512 ?
			FalconParameters::FALCON_512_SIGNATURE_LENGTH :
			FalconParameters::FALCON_1024_SIGNATURE_LENGTH;

		FalconParameters* parameters = new FalconParameters();
		parameters->setParameterSet(parameterSet);

		AsymmetricKeyPair* keyPair = NULL;
		CPPUNIT_ASSERT(falcon->generateKeyPair(&keyPair, parameters));
		CPPUNIT_ASSERT(keyPair != NULL);

		FalconPublicKey* publicKey =
			static_cast<FalconPublicKey*>(keyPair->getPublicKey());
		FalconPrivateKey* privateKey =
			static_cast<FalconPrivateKey*>(keyPair->getPrivateKey());
		CPPUNIT_ASSERT(publicKey != NULL);
		CPPUNIT_ASSERT(privateKey != NULL);
		CPPUNIT_ASSERT(publicKey->isOfType(FalconPublicKey::type));
		CPPUNIT_ASSERT(privateKey->isOfType(FalconPrivateKey::type));
		CPPUNIT_ASSERT(publicKey->getParameterSet() == parameterSet);
		CPPUNIT_ASSERT(privateKey->getParameterSet() == parameterSet);
		CPPUNIT_ASSERT(publicKey->getValue().size() == publicKeyLength);
		CPPUNIT_ASSERT(privateKey->getValue().size() == privateKeyLength);
		CPPUNIT_ASSERT(publicKey->getOutputLength() == signatureLength);
		CPPUNIT_ASSERT(privateKey->getOutputLength() == signatureLength);

		falcon->recycleKeyPair(keyPair);
		falcon->recycleParameters(parameters);
	}

	CPPUNIT_ASSERT(falcon->getMinKeySize() ==
		FalconParameters::FALCON_512_PUB_LENGTH);
	CPPUNIT_ASSERT(falcon->getMaxKeySize() ==
		FalconParameters::FALCON_1024_PUB_LENGTH);
}

void FalconTests::testSerialisation()
{
	CPPUNIT_ASSERT(std::strcmp(OSSL::falconParameterSet2Name(
		FalconParameters::FALCON_512_PARAMETER_SET), "falcon512") == 0);
	CPPUNIT_ASSERT(std::strcmp(OSSL::falconParameterSet2Name(
		FalconParameters::FALCON_1024_PARAMETER_SET), "falcon1024") == 0);
	CPPUNIT_ASSERT(OSSL::falconParameterSet2Name(3UL) == NULL);

	for (const unsigned long parameterSet : allParameterSets)
	{
		FalconParameters* parameters = new FalconParameters();
		parameters->setParameterSet(parameterSet);
		ByteString serialisedParameters = parameters->serialise();

		AsymmetricParameters* reconstructedParameters = NULL;
		CPPUNIT_ASSERT(falcon->reconstructParameters(&reconstructedParameters,
			serialisedParameters));
		CPPUNIT_ASSERT(reconstructedParameters != NULL);
		CPPUNIT_ASSERT(reconstructedParameters->areOfType(FalconParameters::type));
		CPPUNIT_ASSERT(static_cast<FalconParameters*>(reconstructedParameters)->
			getParameterSet() == parameterSet);

		AsymmetricKeyPair* keyPair = NULL;
		CPPUNIT_ASSERT(falcon->generateKeyPair(&keyPair, reconstructedParameters));
		CPPUNIT_ASSERT(keyPair != NULL);

		FalconPublicKey* publicKey =
			static_cast<FalconPublicKey*>(keyPair->getPublicKey());
		FalconPrivateKey* privateKey =
			static_cast<FalconPrivateKey*>(keyPair->getPrivateKey());
		ByteString serialisedKeyPair = keyPair->serialise();
		static_cast<OSSLFalconKeyPair*>(keyPair)->setPrivateKey(
			*static_cast<OSSLFalconPrivateKey*>(privateKey));

		AsymmetricKeyPair* reconstructedKeyPair = NULL;
		CPPUNIT_ASSERT(falcon->reconstructKeyPair(&reconstructedKeyPair,
			serialisedKeyPair));
		CPPUNIT_ASSERT(reconstructedKeyPair != NULL);
		CPPUNIT_ASSERT(serialisedKeyPair.size() == 0);

		FalconPublicKey* reconstructedPublicKey =
			static_cast<FalconPublicKey*>(reconstructedKeyPair->getPublicKey());
		FalconPrivateKey* reconstructedPrivateKey =
			static_cast<FalconPrivateKey*>(reconstructedKeyPair->getPrivateKey());
		CPPUNIT_ASSERT(publicKey->getValue() ==
			reconstructedPublicKey->getValue());
		CPPUNIT_ASSERT(privateKey->getValue() ==
			reconstructedPrivateKey->getValue());
		CPPUNIT_ASSERT(reconstructedPrivateKey->PKCS8Encode().size() != 0);

		ByteString serialisedPublicKey = publicKey->serialise();
		PublicKey* reconstructedPublic = NULL;
		CPPUNIT_ASSERT(falcon->reconstructPublicKey(&reconstructedPublic,
			serialisedPublicKey));
		CPPUNIT_ASSERT(serialisedPublicKey.size() == 0);
		CPPUNIT_ASSERT(publicKey->getValue() ==
			static_cast<FalconPublicKey*>(reconstructedPublic)->getValue());

		ByteString serialisedPrivateKey = privateKey->serialise();
		PrivateKey* reconstructedPrivate = NULL;
		CPPUNIT_ASSERT(falcon->reconstructPrivateKey(&reconstructedPrivate,
			serialisedPrivateKey));
		CPPUNIT_ASSERT(serialisedPrivateKey.size() == 0);
		CPPUNIT_ASSERT(privateKey->getValue() ==
			static_cast<FalconPrivateKey*>(reconstructedPrivate)->getValue());
		CPPUNIT_ASSERT(privateKey->getPublicKeyInfo() ==
			static_cast<FalconPrivateKey*>(reconstructedPrivate)->getPublicKeyInfo());
		CPPUNIT_ASSERT(reconstructedPrivate->PKCS8Encode().size() != 0);

		falcon->recyclePublicKey(reconstructedPublic);
		falcon->recyclePrivateKey(reconstructedPrivate);
		falcon->recycleKeyPair(reconstructedKeyPair);
		falcon->recycleKeyPair(keyPair);
		falcon->recycleParameters(reconstructedParameters);
		falcon->recycleParameters(parameters);
	}
}

void FalconTests::testPKCS8()
{
	for (const unsigned long parameterSet : allParameterSets)
	{
		FalconParameters* parameters = new FalconParameters();
		parameters->setParameterSet(parameterSet);

		AsymmetricKeyPair* keyPair = NULL;
		CPPUNIT_ASSERT(falcon->generateKeyPair(&keyPair, parameters));
		CPPUNIT_ASSERT(keyPair != NULL);

		FalconPrivateKey* privateKey =
			static_cast<FalconPrivateKey*>(keyPair->getPrivateKey());
		ByteString pkcs8 = privateKey->PKCS8Encode();
		OSSLFalconPrivateKey* osslPrivateKey = static_cast<OSSLFalconPrivateKey*>(privateKey);
		CPPUNIT_ASSERT(osslPrivateKey->setFromOSSL(osslPrivateKey->getOSSLKey()));
		CPPUNIT_ASSERT(pkcs8.size() != 0);

		FalconPrivateKey* decodedPrivateKey =
			static_cast<FalconPrivateKey*>(falcon->newPrivateKey());
		CPPUNIT_ASSERT(decodedPrivateKey != NULL);
		CPPUNIT_ASSERT(decodedPrivateKey->PKCS8Decode(pkcs8));
		CPPUNIT_ASSERT_EQUAL(privateKey->getParameterSet(),
			decodedPrivateKey->getParameterSet());
		CPPUNIT_ASSERT(privateKey->getValue() == decodedPrivateKey->getValue());
		CPPUNIT_ASSERT(decodedPrivateKey->PKCS8Encode().size() != 0);

		// CKM_AES_KEY_WRAP zero-pads key data to a multiple of eight bytes.
		ByteString paddedPKCS8 = pkcs8;
		paddedPKCS8.resize((pkcs8.size() + 7) & ~size_t(7));
		CPPUNIT_ASSERT(decodedPrivateKey->PKCS8Decode(paddedPKCS8));
		CPPUNIT_ASSERT(privateKey->getValue() == decodedPrivateKey->getValue());

		falcon->recyclePrivateKey(decodedPrivateKey);
		falcon->recycleKeyPair(keyPair);
		falcon->recycleParameters(parameters);
	}
}

void FalconTests::testSigning()
{
	for (const unsigned long parameterSet : allParameterSets)
	{
		FalconParameters* parameters = new FalconParameters();
		parameters->setParameterSet(parameterSet);

		AsymmetricKeyPair* keyPair = NULL;
		CPPUNIT_ASSERT(falcon->generateKeyPair(&keyPair, parameters));
		CPPUNIT_ASSERT(keyPair != NULL);

		ByteString dataToSign("0123456789abcdef");
		ByteString signature;
		CPPUNIT_ASSERT(falcon->sign(keyPair->getPrivateKey(), dataToSign,
			signature, AsymMech::FALCON));
		CPPUNIT_ASSERT(signature.size() > 0);
		CPPUNIT_ASSERT(signature.size() <=
			keyPair->getPrivateKey()->getOutputLength());
		CPPUNIT_ASSERT(verifyFalconSignature(
			static_cast<FalconPublicKey*>(keyPair->getPublicKey()),
			dataToSign, signature));

		CPPUNIT_ASSERT(!falcon->sign(NULL, dataToSign, signature,
			AsymMech::FALCON));
		CPPUNIT_ASSERT(!falcon->sign(keyPair->getPrivateKey(), dataToSign,
			signature, AsymMech::Unknown));

		falcon->recycleKeyPair(keyPair);
		falcon->recycleParameters(parameters);
	}
}

void FalconTests::testSigningWithReconstructedPrivateKey()
{
	for (const unsigned long parameterSet : allParameterSets)
	{
		FalconParameters* parameters = new FalconParameters();
		parameters->setParameterSet(parameterSet);

		AsymmetricKeyPair* keyPair = NULL;
		CPPUNIT_ASSERT(falcon->generateKeyPair(&keyPair, parameters));
		CPPUNIT_ASSERT(keyPair != NULL);

		ByteString serialisedPrivateKey = keyPair->getPrivateKey()->serialise();
		PrivateKey* reconstructedPrivateKey = NULL;
		CPPUNIT_ASSERT(falcon->reconstructPrivateKey(&reconstructedPrivateKey,
			serialisedPrivateKey));
		CPPUNIT_ASSERT(reconstructedPrivateKey != NULL);
		CPPUNIT_ASSERT(serialisedPrivateKey.size() == 0);

		ByteString dataToSign("fedcba9876543210");
		ByteString signature;
		CPPUNIT_ASSERT(falcon->sign(reconstructedPrivateKey, dataToSign,
			signature, AsymMech::FALCON));
		CPPUNIT_ASSERT(signature.size() > 0);
		CPPUNIT_ASSERT(signature.size() <=
			keyPair->getPrivateKey()->getOutputLength());
		CPPUNIT_ASSERT(verifyFalconSignature(
			static_cast<FalconPublicKey*>(keyPair->getPublicKey()),
			dataToSign, signature));

		falcon->recyclePrivateKey(reconstructedPrivateKey);
		falcon->recycleKeyPair(keyPair);
		falcon->recycleParameters(parameters);
	}
}

void FalconTests::testVerification()
{
	for (const unsigned long parameterSet : allParameterSets)
	{
		FalconParameters* parameters = new FalconParameters();
		parameters->setParameterSet(parameterSet);

		AsymmetricKeyPair* keyPair = NULL;
		CPPUNIT_ASSERT(falcon->generateKeyPair(&keyPair, parameters));
		CPPUNIT_ASSERT(keyPair != NULL);

		ByteString data("0123456789abcdef");
		ByteString signature;
		CPPUNIT_ASSERT(falcon->sign(keyPair->getPrivateKey(), data, signature,
			AsymMech::FALCON));
		CPPUNIT_ASSERT(falcon->verify(keyPair->getPublicKey(), data, signature,
			AsymMech::FALCON));

		ByteString alteredData(data);
		alteredData[0] ^= 1;
		CPPUNIT_ASSERT(!falcon->verify(keyPair->getPublicKey(), alteredData,
			signature, AsymMech::FALCON));

		ByteString alteredSignature(signature);
		alteredSignature[alteredSignature.size() - 1] ^= 1;
		CPPUNIT_ASSERT(!falcon->verify(keyPair->getPublicKey(), data,
			alteredSignature, AsymMech::FALCON));

		ByteString emptySignature;
		CPPUNIT_ASSERT(!falcon->verify(keyPair->getPublicKey(), data,
			emptySignature, AsymMech::FALCON));
		ByteString oversizedSignature;
		oversizedSignature.resize(
			keyPair->getPrivateKey()->getOutputLength() + 1);
		CPPUNIT_ASSERT(!falcon->verify(keyPair->getPublicKey(), data,
			oversizedSignature, AsymMech::FALCON));
		CPPUNIT_ASSERT(!falcon->verify(NULL, data, signature,
			AsymMech::FALCON));
		CPPUNIT_ASSERT(!falcon->verify(keyPair->getPublicKey(), data, signature,
			AsymMech::Unknown));

		falcon->recycleKeyPair(keyPair);
		falcon->recycleParameters(parameters);
	}
}

// Test vectors count 0 and 1 from falcon512-KAT.rsp and falcon1024-KAT.rsp in
// https://falcon-sign.info/falcon-round3.zip. The KAT signed-message encoding
// is converted to the detached compressed signature encoding used by liboqs.
// Detached format: (0x30 + logn), the 40-byte nonce, then the compressed
// signature without its original (0x20 + logn) header.
void FalconTests::testSignVerifyKnownVector()
{
	// public key, private key, message, signature
	const char* testVectors[][4] =
	{
		{
			"",
			"",
			"D81C4D8D734FCBFBEADE3D3F8A039FAA2A2C9957E835AD55B22E75BF57BB556AC8",
			""
		},
		{
			"",
			"",
			"225D5CE2CEAC61930A07503FB59F7C2F936A3E075481DA3CA299A80F8C5DF9223A073E7B90E02EBF98CA2227EBA38C1AB2568209E46DBA961869C6F83983B17DCD49",
			""
		},
		// Falcon-1024, count 0.
		{
			"",
			"",
			"D81C4D8D734FCBFBEADE3D3F8A039FAA2A2C9957E835AD55B22E75BF57BB556AC8",
			""
		},
		// Falcon-1024, count 1.
		{
			"",
			"",
			"225D5CE2CEAC61930A07503FB59F7C2F936A3E075481DA3CA299A80F8C5DF9223A073E7B90E02EBF98CA2227EBA38C1AB2568209E46DBA961869C6F83983B17DCD49",
			""
		}
	};

	for (size_t i = 0; i < sizeof(testVectors) / sizeof(testVectors[0]); i++)
	{
		FalconPublicKey* pubKey = (FalconPublicKey*) falcon->newPublicKey();
		FalconPrivateKey* privKey = (FalconPrivateKey*) falcon->newPrivateKey();
		CPPUNIT_ASSERT(pubKey != NULL);
		CPPUNIT_ASSERT(privKey != NULL);

		pubKey->setValue(ByteString(testVectors[i][0]));
		privKey->setValue(ByteString(testVectors[i][1]));
		ByteString data(testVectors[i][2]);
		ByteString goodSignature(testVectors[i][3]);

		// Changing a nonce byte invalidates the signature
		ByteString badSignature(goodSignature);
		badSignature[5] ^= 0x01;

		CPPUNIT_ASSERT(falcon->verify(pubKey, data, goodSignature, AsymMech::FALCON));
		CPPUNIT_ASSERT(!falcon->verify(pubKey, data, badSignature, AsymMech::FALCON));

		ByteString signature;
		CPPUNIT_ASSERT(falcon->sign(privKey, data, signature, AsymMech::FALCON));
		CPPUNIT_ASSERT(falcon->verify(pubKey, data, signature, AsymMech::FALCON));

		falcon->recyclePublicKey(pubKey);
		falcon->recyclePrivateKey(privKey);
	}
}

void FalconTests::testInvalidInputs()
{
	FalconParameters* parameters = new FalconParameters();
	parameters->setParameterSet(FalconParameters::FALCON_512_PARAMETER_SET);
	AsymmetricKeyPair* keyPair = NULL;

	CPPUNIT_ASSERT(!falcon->generateKeyPair(NULL, parameters));
	CPPUNIT_ASSERT(!falcon->generateKeyPair(&keyPair, NULL));

	FalconParameters* unsupportedParameters = new FalconParameters();
	unsupportedParameters->setParameterSet(3UL);
	CPPUNIT_ASSERT(!falcon->generateKeyPair(&keyPair, unsupportedParameters));
	CPPUNIT_ASSERT(keyPair == NULL);

	AsymmetricParameters* reconstructedParameters = NULL;
	ByteString malformedParameters("00");
	CPPUNIT_ASSERT(!falcon->reconstructParameters(&reconstructedParameters,
		malformedParameters));
	CPPUNIT_ASSERT(reconstructedParameters == NULL);
	ByteString unsupportedSerialisedParameters(3UL);
	CPPUNIT_ASSERT(!falcon->reconstructParameters(&reconstructedParameters,
		unsupportedSerialisedParameters));
	CPPUNIT_ASSERT(reconstructedParameters == NULL);

	ByteString shortPublicKey;
	shortPublicKey.resize(FalconParameters::FALCON_512_PUB_LENGTH - 1);
	ByteString serialisedShortPublicKey = shortPublicKey.serialise();
	PublicKey* publicKey = NULL;
	CPPUNIT_ASSERT(!falcon->reconstructPublicKey(&publicKey,
		serialisedShortPublicKey));
	CPPUNIT_ASSERT(publicKey == NULL);

	ByteString shortPrivateKey;
	shortPrivateKey.resize(FalconParameters::FALCON_512_PRIV_LENGTH - 1);
	ByteString serialisedShortPrivateKey = shortPrivateKey.serialise();
	PrivateKey* privateKey = NULL;
	CPPUNIT_ASSERT(!falcon->reconstructPrivateKey(&privateKey,
		serialisedShortPrivateKey));
	CPPUNIT_ASSERT(privateKey == NULL);

	ByteString emptyPublicKey = ByteString().serialise();
	ByteString emptyPrivateKey = ByteString().serialise();
	ByteString emptyKeyPair = emptyPublicKey.serialise() +
		emptyPrivateKey.serialise();
	CPPUNIT_ASSERT(!falcon->reconstructKeyPair(NULL, emptyKeyPair));
	CPPUNIT_ASSERT(!falcon->reconstructPublicKey(NULL, emptyPublicKey));
	CPPUNIT_ASSERT(!falcon->reconstructPrivateKey(NULL, emptyPrivateKey));

	FalconPrivateKey* invalidPKCS8Key =
		static_cast<FalconPrivateKey*>(falcon->newPrivateKey());
	CPPUNIT_ASSERT(invalidPKCS8Key != NULL);
	ByteString invalidPKCS8("00");
	CPPUNIT_ASSERT(!invalidPKCS8Key->PKCS8Decode(invalidPKCS8));

	falcon->recyclePrivateKey(invalidPKCS8Key);
	falcon->recycleParameters(unsupportedParameters);
	falcon->recycleParameters(parameters);
}

#endif // WITH_FALCON
